const incoming = $input.first().json;
const trigger = incoming.body ?? incoming;
const headers = incoming.headers ?? {};
const automationSecret = headers['x-automation-secret'] || headers['X-Automation-Secret'] || '';

const contextUrl = trigger.app?.contextUrl ?? '';
const callbackUrl = trigger.app?.callbackUrl ?? '';
const jobUrl = trigger.job?.url ?? '';

if (!/^https?:\/\//.test(contextUrl)) {
  throw new Error('Invalid context URL in webhook payload');
}
if (!/^https?:\/\//.test(callbackUrl)) {
  throw new Error('Invalid callback URL in webhook payload');
}
if (!/^https?:\/\//.test(jobUrl)) {
  throw new Error('Invalid job URL in webhook payload');
}
if (!automationSecret) {
  throw new Error('Missing automation secret header on webhook request');
}

return [{ json: { reason: trigger.reason ?? 'queued', run: trigger.run ?? {}, job: trigger.job ?? {}, profile: trigger.profile ?? {}, app: trigger.app ?? {}, contextUrl, callbackUrl, jobUrl, automationSecret } }];

const dispatch = $('Prepare Dispatch Input').item.json || {};
const context = $input.first().json || {};
const run = context.run || dispatch.run || {};
const job = run.job || dispatch.job || {};
const profile = context.profile || dispatch.profile || {};
const answers = run.answers || {};
const siteType = String(run.siteType || dispatch.run?.siteType || '').toUpperCase();
const jobUrl = job.url || dispatch.jobUrl || '';
if (!jobUrl) throw new Error('Missing job URL for Browserbase task');

const answerLines = Object.entries(answers).length
  ? Object.entries(answers).map(([question, answer]) => '- ' + question + ': ' + answer).join('\n')
  : '- none';

const siteHintLines = [];
if (siteType === 'COMEET' || /comeet\.com/i.test(jobUrl)) {
  siteHintLines.push('- This is likely a Comeet-hosted application. The initial page may be a job description page rather than the actual form.');
  siteHintLines.push('- Prioritize the main application CTA, especially text like "Apply for this job", "Apply", "Submit application", or "Start application".');
  siteHintLines.push('- After clicking a CTA, inspect iframes, embedded widgets, drawers, modals, sticky sidebars, and below-the-fold content for the actual form.');
}

const instruction = [
  'Complete this job application if possible.',
  'You must first reach the real application form before attempting to fill fields.',
  'If the current page is only a listing/details page, find the main application CTA and click it.',
  'Search visible buttons and links for application entry points, especially "Apply for this job", "Apply", "Submit application", or "Start application".',
  'Scroll as needed and inspect top sections, sticky sidebars, lower sections, modals, drawers, embeds, and iframes after each click.',
  'Once the form is visible, fill visible contact fields directly before attempting anything else:',
  '- full name using %full_name%',
  '- email using %email%',
  '- phone using %phone%',
  'If LinkedIn, GitHub, or portfolio fields are visible, fill them using %linkedin_url%, %github_url%, and %portfolio_url% when available.',
  'Do not use Tab/Enter to guess field order when visible text inputs are present. Prefer direct click-and-fill actions on named fields.',
  'Never attempt to submit until all visible required contact fields are filled.',
  'If a resume upload is required, stop and report NEEDS_INPUT because resume file upload is not available in this Browserbase flow.',
  'If login, captcha, human verification, OTP, work authorization, or an unknown required answer blocks progress, stop and report NEEDS_INPUT.',
  'Only report SUBMITTED if the application was clearly submitted.',
  '',
  'Target job:',
  '- Title: ' + (job.title || ''),
  '- Company: ' + (job.company || ''),
  '- URL: ' + jobUrl,
  '',
  'Saved answers for this run:',
  answerLines,
  '',
  ...siteHintLines,
  '',
  'When you finish, your final message must start with these exact lines:',
  'FINAL_STATUS: SUBMITTED or NEEDS_INPUT or FAILED',
  'MESSAGE: short explanation',
  'BLOCKER: blocker text or none',
  'INPUT_FIELD: one of manual_review, login, human_verification, resume_upload, work_authorization, unknown_required_answer, none',
  'PAGE_STATE: short description of the final page state',
  'ATTEMPTED_ACTIONS: comma-separated summary of actions you took'
].join('\n');

const systemPrompt = [
  'You are a careful job-application automation agent.',
  'Treat the task as incomplete unless one of these is true: application submitted, a concrete blocker was reached, or the site/tool genuinely failed.',
  'Do not finish early just because the first page has no form fields.',
  'Before declaring the form missing, you must try to enter the application flow and inspect iframe/embed states explicitly.',
  'When contact inputs are visible, directly fill them before any submit attempt.',
  'Avoid keyboard-only navigation if labeled inputs are visible; prefer direct click-and-fill actions.',
  'Never invent data. If required information is missing, say so in the final structured message.',
  'Use the exact final message format requested by the instruction.'
].join('\n');

return [{ json: {
  ...dispatch,
  ...context,
  run,
  job,
  profile,
  siteType,
  jobUrl,
  browserbaseInstruction: instruction,
  browserbaseSystemPrompt: systemPrompt,
} }];

const result = $input.first().json || {};
const state = $('Prepare Browserbase Task').item.json || {};
const sessionId = typeof result.sessionId === 'string' ? result.sessionId : '';
const sessionUrl = sessionId ? 'https://browserbase.com/sessions/' + sessionId : undefined;
const replayUrl = sessionUrl;
const rawMessage = typeof result.message === 'string' ? result.message : typeof result.error === 'string' ? result.error : 'Browserbase returned no message.';
const lines = rawMessage.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
const readMarker = (name) => {
  const line = lines.find((entry) => entry.toUpperCase().startsWith(name + ':'));
  return line ? line.slice(name.length + 1).trim() : '';
};
const finalStatus = (readMarker('FINAL_STATUS') || '').toUpperCase();
const finalMessage = readMarker('MESSAGE') || rawMessage;
const blocker = readMarker('BLOCKER');
const inputField = readMarker('INPUT_FIELD').toLowerCase();
const pageState = readMarker('PAGE_STATE');
const attemptedActions = readMarker('ATTEMPTED_ACTIONS');
const serialized = JSON.stringify(result).toLowerCase();
const needsInputPattern = /(captcha|human verification|verify you are human|otp|two-factor|2fa|login|sign in|authorization|work authorization|resume upload|upload.*resume|required file|manual review|manual attention|missing answer)/i;
const submittedPattern = /(application submitted|submitted successfully|thank you for applying|your application has been submitted)/i;

const browserbasePayload = {
  sessionId,
  sessionUrl,
  replayUrl,
  taskStatus: result.error ? 'FAILED' : (result.completed === false ? 'INCOMPLETE' : 'COMPLETED'),
  completed: result.completed,
  actions: Array.isArray(result.actions) ? result.actions : [],
  usage: result.usage ?? null,
  raw: result,
};

let finalPayload;
if (result.error || result.success === false) {
  const message = finalMessage || rawMessage;
  if (needsInputPattern.test(message)) {
    finalPayload = {
      status: 'NEEDS_INPUT',
      needsInput: true,
      currentStep: 'Waiting for user attention',
      blockingQuestion: blocker && blocker.toLowerCase() !== 'none' ? blocker : message,
      inputField: inputField && inputField !== 'none' ? inputField : 'manual_review',
      message,
      level: 'WARN',
      payload: { browserbase: browserbasePayload },
    };
  } else {
    finalPayload = {
      status: 'FAILED',
      currentStep: 'Automation failed',
      lastError: message,
      message,
      level: 'ERROR',
      payload: { browserbase: browserbasePayload },
    };
  }
} else if (finalStatus === 'SUBMITTED' || submittedPattern.test(rawMessage)) {
  finalPayload = {
    status: 'SUBMITTED',
    currentStep: 'Application submitted',
    message: finalMessage,
    payload: { browserbase: browserbasePayload },
  };
} else if (finalStatus === 'NEEDS_INPUT' || needsInputPattern.test(rawMessage)) {
  finalPayload = {
    status: 'NEEDS_INPUT',
    needsInput: true,
    currentStep: 'Waiting for user attention',
    blockingQuestion: blocker && blocker.toLowerCase() !== 'none' ? blocker : finalMessage,
    inputField: inputField && inputField !== 'none' ? inputField : 'manual_review',
    message: [finalMessage, pageState ? 'Page state: ' + pageState : '', attemptedActions ? 'Actions: ' + attemptedActions : ''].filter(Boolean).join(' '),
    level: 'WARN',
    payload: { browserbase: browserbasePayload },
  };
} else if (finalStatus === 'FAILED') {
  finalPayload = {
    status: 'FAILED',
    currentStep: 'Automation failed',
    lastError: [finalMessage, pageState ? 'Page state: ' + pageState : '', attemptedActions ? 'Actions: ' + attemptedActions : ''].filter(Boolean).join(' '),
    message: [finalMessage, pageState ? 'Page state: ' + pageState : '', attemptedActions ? 'Actions: ' + attemptedActions : ''].filter(Boolean).join(' '),
    level: 'ERROR',
    payload: { browserbase: browserbasePayload },
  };
} else {
  finalPayload = {
    status: 'NEEDS_INPUT',
    needsInput: true,
    currentStep: 'Waiting for user attention',
    blockingQuestion: 'Browserbase finished without a clear terminal status. Inspect the replay to continue.',
    inputField: 'manual_review',
    message: [finalMessage, pageState ? 'Page state: ' + pageState : '', attemptedActions ? 'Actions: ' + attemptedActions : ''].filter(Boolean).join(' '),
    level: 'WARN',
    payload: { browserbase: browserbasePayload },
  };
}

return [{ json: { finalPayload } }];
